'use strict';

// pubspec.lock is generated by pub, so its shape is fixed:
//
//   packages:
//     async:
//       dependency: transitive
//       description:
//         name: async
//         sha256: "…"
//         url: "https://pub.dev"
//       source: hosted
//       version: "2.13.0"
//
// That regularity is the whole reason a line reader is enough here.

function unquote(s) {
  const t = s.trim();
  if (t.length >= 2 && (t[0] === '"' || t[0] === "'") && t[t.length - 1] === t[0]) {
    return t.slice(1, -1);
  }
  return t;
}

/**
 * @typedef {{
 *   name: string,
 *   dependency: string,   // "direct main" | "direct dev" | "direct overridden" | "transitive"
 *   source: string,       // "hosted" | "sdk" | "path" | "git"
 *   version: string|null,
 *   url: string|null,     // hosted server, e.g. https://pub.dev
 *   path: string|null,    // for path packages; the sub-path for git ones
 *   relative: boolean,
 *   resolvedRef: string|null, // git commit
 * }} LockedPackage
 */

/**
 * @param {string} text the pubspec.lock contents
 * @returns {Map<string, LockedPackage>}
 */
function parseLock(text) {
  /** @type {Map<string, LockedPackage>} */
  const packages = new Map();
  let inPackages = false;
  /** @type {LockedPackage|null} */
  let current = null;
  let inDescription = false;

  for (const raw of text.split(/\r?\n/)) {
    if (!raw.trim() || raw.trim().startsWith('#')) continue;
    const indent = raw.length - raw.trimStart().length;
    const body = raw.trim();

    if (indent === 0) {
      inPackages = body === 'packages:';
      current = null;
      continue;
    }
    if (!inPackages) continue;

    if (indent === 2) {
      const m = body.match(/^"?([\w]+)"?\s*:\s*$/);
      current = m
        ? {
          name: m[1], dependency: '', source: '', version: null,
          url: null, path: null, relative: false, resolvedRef: null,
        }
        : null;
      if (current) packages.set(current.name, current);
      inDescription = false;
      continue;
    }
    if (!current) continue;

    const kv = body.match(/^([\w-]+)\s*:\s*(.*)$/);
    if (!kv) continue;
    const [, key, rawValue] = kv;
    const value = unquote(rawValue);

    if (indent === 4) {
      inDescription = key === 'description';
      if (key === 'dependency') current.dependency = value;
      else if (key === 'source') current.source = value;
      else if (key === 'version') current.version = value;
      // A plain `description: flutter` (sdk packages) has no nested map.
    } else if (indent >= 6 && inDescription) {
      if (key === 'url') current.url = value;
      else if (key === 'path') current.path = value;
      else if (key === 'relative') current.relative = value === 'true';
      else if (key === 'resolved-ref') current.resolvedRef = value;
    }
  }
  return packages;
}

module.exports = { parseLock };
